import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        long time = 0;   // instante do último evento processado
        long gap = 1;    // intervalo até o próximo evento (padrão: 1 segundo)
        long[] pendingSince = new long[101];
        boolean[] hasPending = new boolean[101];
        long[] total = new long[101];
        boolean[] seen = new boolean[101];

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            char type = st.nextToken().charAt(0);
            int x = Integer.parseInt(st.nextToken());

            if (type == 'T') {
                gap = x;
            } else {
                // Um evento ocorre: aplica o intervalo registrado e restaura o padrão
                time += gap;
                gap = 1;
                seen[x] = true;

                if (type == 'R') {
                    // Mensagem recebida: registra instante da mensagem pendente
                    hasPending[x] = true;
                    pendingSince[x] = time;
                } else { // 'E'
                    // Resposta enviada: acumula tempo de resposta
                    if (hasPending[x]) {
                        total[x] += time - pendingSince[x];
                        hasPending[x] = false;
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int f = 1; f <= 100; f++) {
            if (seen[f]) {
                sb.append(f).append(' ')
                  .append(hasPending[f] ? -1 : total[f])
                  .append('\n');
            }
        }
        System.out.print(sb);
    }
}
